3: struct ResearchDocument {
4:     let path: String
5:     let text: String
6: }
7: 
8: enum ResearchExport {
9:     static func documents(_ binaries: [EmbeddedBinary], packageName: String, selectedTopic: String) -> [ResearchDocument] {
10:         var docs: [ResearchDocument] = []
11:         let selected = GuidedAnalysis.topics.first(where: { $0.id == selectedTopic }) ?? GuidedAnalysis.topics[0]
12:         var index = ["# ReverseLab research package", "", "Package: \(packageName)", "Mach-O count: \(binaries.count)", "Selected topic: \(selected.title)", "", "## How to use with GPT", "Upload this ZIP and ask GPT to first read 00_START_HERE.md and 01_INDEX.txt, then inspect the requested topic and binary reports. Cite actual binary name and evidence line; do not treat string matches as verified execution paths.", "", "## Limits", "Data are extracted by the current static parser. String/symbol/instruction caps may truncate results. No decompiler or dynamic tracing is included."]
13:         var summary: [String] = ["BINARY INDEX", "Package: \(packageName)"]
14:         var topicAll: [String: [String]] = [:]
15:         for topic in GuidedAnalysis.topics { topicAll[topic.id] = ["TOPIC: \(topic.title)", "PURPOSE: \(topic.purpose)", "Evidence below is a keyword candidate, NOT proof of runtime behavior."] }
16:         for (i, binary) in binaries.enumerated() {
17:             let base = String(format: "Binaries/%02d_%@", i+1, safeName((binary.path as NSString).lastPathComponent))
18:             do {
19:                 let r = try MachOAnalyzer.analyze(binary.data, name: binary.path)
20:                 summary += ["", "\(i+1). \(binary.path)", "   \(r.architecture) | \(r.fileType) | \(r.size) bytes", "   Symbols: \(r.symbols.count); strings: \(r.strings.count); ObjC: \(r.objcMetadata.count); branches: \(r.crossReferences.count)"]
21:                 docs += [
22:                     .init(path: base+"/00_Overview.txt", text: (["File: \(binary.path)", "Arch: \(r.architecture)", "Type: \(r.fileType)", "Size: \(r.size)", "Load commands: \(r.commands)", "", "SEGMENTS"] + r.segments + ["", "DEPENDENCIES"] + r.dependencies + ["", "LIMITATIONS"] + r.warnings).joined(separator: "\n")),
23:                     .init(path: base+"/01_Symbols.txt", text: r.symbols.joined(separator: "\n")),
24:                     .init(path: base+"/02_Strings.txt", text: r.strings.joined(separator: "\n")),
25:                     .init(path: base+"/03_ObjC.txt", text: r.objcMetadata.joined(separator: "\n")),
26:                     .init(path: base+"/04_Disassembly.txt", text: r.disassembly.joined(separator: "\n")),
27:                     .init(path: base+"/05_Branch_Xrefs.txt", text: r.crossReferences.joined(separator: "\n"))
28:                 ]
29:                 for topic in GuidedAnalysis.topics {
30:                     let hits = GuidedAnalysis.hits(r, topic: topic, limit: Int.max)
31:                     topicAll[topic.id, default: []].append("\n### \(binary.path) | \(hits.count) matches")
32:                     topicAll[topic.id, default: []].append(contentsOf: hits.map { "[\($0.source)] \($0.value)" })
33:                 }
34:             } catch {
35:                 summary += ["", "\(i+1). \(binary.path): ERROR \(error.localizedDescription)"]
36:             }
37:         }
38:         for topic in GuidedAnalysis.topics {
39:             docs.append(.init(path: "Topics/\(topic.id)_\(safeName(topic.title)).txt", text: (topicAll[topic.id] ?? []).joined(separator: "\n")))
40:         }
41:         index += ["", "## Contents", "01_INDEX.txt: all binaries", "Topics/: research topics across ALL binaries", "Binaries/: separate original extracted results for EACH binary", "", "## Data integrity", "All exported lines originate from this app's parser; no original source code is reconstructed. Binary Mach-O bytes are not included in this report ZIP."]
42:         docs.insert(.init(path: "01_INDEX.txt", text: summary.joined(separator: "\n")), at: 0)
43:         docs.insert(.init(path: "00_START_HERE.md", text: index.joined(separator: "\n")), at: 0)
44:         return docs
45:     }
46:     private static func safeName(_ value: String) -> String {
47:         let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "._-"))
48:         let cleaned = String(value.unicodeScalars.map { allowed.contains($0) ? Character($0) : "_" })
49:         return String(cleaned.prefix(80))
50:     }
51:     static func createZIP(_ docs: [ResearchDocument], name: String) throws -> URL {
52:         let dest = FileManager.default.temporaryDirectory.appendingPathComponent("ReverseLab-\(safeName(name))-Research.zip")
53:         let tmp = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".zip")
54:         FileManager.default.createFile(atPath: tmp.path, contents: nil)
55:         let handle = try FileHandle(forWritingTo: tmp)
56:         defer { try? handle.close() }
57:         var central = Data()
58:         var position: UInt32 = 0
59:         var count = 0
60:         for doc in docs {
61:             let file = Data(doc.text.utf8)
62:             let path = Data(doc.path.utf8)
63:             guard file.count < Int(UInt32.max), path.count < 65535, position < UInt32.max else { throw NSError(domain: "ReverseLab", code: 2, userInfo: [NSLocalizedDescriptionKey:"报告太大，无法生成 ZIP32"]) }
64:             let checksum = crc32(file)
65:             var local = Data()
66:             local.put32(0x04034b50); local.put16(20); local.put16(0x0800); local.put16(0); local.put16(0); local.put16(0)
67:             local.put32(checksum); local.put32(UInt32(file.count)); local.put32(UInt32(file.count)); local.put16(UInt16(path.count)); local.put16(0)
68:             try handle.write(contentsOf: local); try handle.write(contentsOf: path); try handle.write(contentsOf: file)
69:             var c = Data()
70:             c.put32(0x02014b50); c.put16(20); c.put16(20); c.put16(0x0800); c.put16(0); c.put16(0); c.put16(0)
71:             c.put32(checksum); c.put32(UInt32(file.count)); c.put32(UInt32(file.count)); c.put16(UInt16(path.count)); c.put16(0); c.put16(0)
72:             c.put16(0); c.put16(0); c.put32(0); c.put32(position)
73:             c.append(path); central.append(c)
74:             let delta = local.count + path.count + file.count
75:             guard UInt64(position)+UInt64(delta) < UInt64(UInt32.max) else { throw NSError(domain:"ReverseLab",code:3,userInfo:[NSLocalizedDescriptionKey:"ZIP 超过 4GB 限制"]) }
76:             position += UInt32(delta); count += 1
77:         }
78:         guard central.count < Int(UInt32.max), count < 65535 else { throw NSError(domain:"ReverseLab",code:4,userInfo:[NSLocalizedDescriptionKey:"ZIP 条目过多"]) }
79:         try handle.write(contentsOf: central)
80:         var end = Data()
81:         end.put32(0x06054b50); end.put16(0); end.put16(0); end.put16(UInt16(count)); end.put16(UInt16(count))
82:         end.put32(UInt32(central.count)); end.put32(position); end.put16(0)
83:         try handle.write(contentsOf: end)
84:         try? FileManager.default.removeItem(at: dest)
85:         try FileManager.default.moveItem(at: tmp, to: dest)
86:         return dest
87:     }
88:     private static func crc32(_ data: Data) -> UInt32 {
89:         var crc: UInt32 = 0xffffffff
90:         for byte in data {
91:             crc ^= UInt32(byte)
92:             for _ in 0..<8 { crc = (crc >> 1) ^ ((crc & 1) != 0 ? 0xedb88320 : 0) }
93:         }
94:         return ~crc
95:     }
96: }
97: private extension Data {
98:     mutating func put16(_ value: UInt16) { append(UInt8(truncatingIfNeeded:value)); append(UInt8(truncatingIfNeeded:value >> 8)) }
99:     mutating func put32(_ value: UInt32) { put16(UInt16(truncatingIfNeeded:value)); put16(UInt16(truncatingIfNeeded:value >> 16)) }
100: }
